fn reserve(
    used: usize,
    next: usize,
    limit: usize,
) -> Option<usize> {
    let total = used.checked_add(next)?;
    (total <= limit).then_some(total)
}
fn main() {
    assert_eq!(reserve(8, 2, 10), Some(10));
    assert_eq!(reserve(8, 3, 10), None);
}

